module Controller_BEH (  output 		Ready,   output reg 	Load_regs,   output		Incr_R2, Shift_left,   input 		Start, Zero, E, clock, reset_b);  parameter S_idle = 0, S_1 = 1, S_2 = 2, S_3 = 3;  reg [1:0] state, next_state;  assign Ready = (state == S_idle);  assign Incr_R2 = (state == S_1);  assign Shift_left = (state == S_2);  always @ (posedge clock, negedge reset_b)    if (reset_b == 0) state <= S_idle;    else state <= next_state;  always @ (state, Start, Zero, E) begin    Load_regs = 0;    case (state)      S_idle:		if (Start) begin Load_regs = 1; next_state = S_1; end 				else next_state = S_idle;      S_1:		if (Zero) next_state = S_idle; else next_state = S_2;	      S_2:		next_state = S_3;      S_3:		if (E) next_state = S_1; else next_state = S_2;    endcase  endendmodule// Test plan for Control Unit // Verify that state enters S_idle with reset_b asserted.// With reset_b de-asserted, verify that state enters S_1 and asserts Load_Regs when // Start is asserted.// Verify that Incr_R2 is asserted in S_1.// Verify that state returns to S_idle from S_1 if Zero is asserted.// Verify that state goes to S_2 if Zero is not asserted.// Verify that Shift_left is asserted in S_2.// Verify that state goes to S_3 from S_2 unconditionally.//  Verify that state returns to S_2 from S_3 id E is not asserted.// Verify that state goes to S_1 from S_3 if E is asserted.// Test bench for Control Unitmodule t_Control_Unit ();  wire Ready, Load_regs, Incr_R2, Shift_left;   reg Start, Zero, E, clock, reset_b;  Controller_BEH M0 (Ready, Load_regs, Incr_R2, Shift_left, Start, Zero, E, clock, reset_b);  initial #250 $finish;  initial begin clock = 0; forever #5 clock = ~clock; end  initial begin reset_b = 0; #2 reset_b = 1; end  initial fork    Zero = 1;    E = 0;    Start = 0;    #20 Start = 1;	// Cycle from S_idle to S_1    #80 Start = 0;    #70 Zero = 0;	// S_idle to S_1 to S_2 to S_3 and cycle to S_2.    #130 E = 1;	// Cycle to S_3 to S_1 to S_2 to S_3    #150 Zero = 1;	// Return to S_idle  joinendmodule